package me.rezapour.f1appserver.apiimport me.rezapour.f1appserver.api.model.DriverDtoimport me.rezapour.f1appserver.api.model.DriversResponseimport org.springframework.stereotype.Componentimport org.springframework.web.client.ResourceAccessExceptionimport org.springframework.web.client.RestClientimport org.springframework.web.client.RestClientResponseException@Componentclass F1ApiClient(    private val restClientBuilder: RestClient.Builder) {    private val client = restClientBuilder        .baseUrl("https://api.jolpi.ca")        .build()    fun getDrivers(): List<DriverDto>? {        return try {            client.get()                .uri("/ergast/f1/drivers/")                .retrieve()                .body(DriversResponse::class.java)                ?.data?.driverTable?.drivers        } catch (e: RestClientResponseException) {            throw F1ApiResponseException("Network Error", e)        } catch (e: ResourceAccessException) {            throw F1ApiConnectionException("Network Error", e)        }    }}